import{_ as n,a as t,b as s,c as i,d as a,e as r,f as d,g as l,h as o}from"./chunks/events.DLZbqLJC.js";import{_ as h,o as c,c as u,a3 as p}from"./chunks/framework.BlfGB29P.js";const E=JSON.parse('{"title":"USB Extender für Home Assistant","description":"USB-Tasten, Stream Decks und Makropads über bis zu drei MQTT-Broker verbinden. Installation, Anlernen, Topics und Praxistest mit Bildern.","frontmatter":{"title":"USB Extender für Home Assistant","description":"USB-Tasten, Stream Decks und Makropads über bis zu drei MQTT-Broker verbinden. Installation, Anlernen, Topics und Praxistest mit Bildern."},"headers":[],"relativePath":"projects/usb-extender/index.md","filePath":"projects/usb-extender/index.md","lastUpdated":1795267108000}'),k={name:"projects/usb-extender/index.md"};function g(b,e,m,f,F,B){return c(),u("div",null,[...e[0]||(e[0]=[p('<h1 id="usb-extender-fur-home-assistant" tabindex="-1">USB Extender für Home Assistant <a class="header-anchor" href="#usb-extender-fur-home-assistant" aria-label="Permalink to &quot;USB Extender für Home Assistant&quot;">​</a></h1><p><strong>0.1.5 · Raspberry Pi · Stand 21. November 2026</strong></p><p>Eine USB-Tastatur am Raspberry Pi kann zum Bedienteil für Home Assistant oder ioBroker werden. Der USB Extender erkennt Eingaben und sendet sie über MQTT an bis zu <strong>drei Broker gleichzeitig</strong>. Die Weboberfläche dient zum Einrichten und kann danach abgeschaltet werden; USB und MQTT laufen unabhängig weiter.</p><p><a href="https://github.com/rockbaer2007/usb-extender-home-assistant" target="_blank" rel="noreferrer">GitHub / README DE und EN</a> · <a href="https://github.com/rockbaer2007/usb-extender-home-assistant/releases/tag/v0.1.5" target="_blank" rel="noreferrer">ZIP 0.1.5</a> · <a href="https://github.com/rockbaer2007/usb-extender-home-assistant/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">Änderungen</a></p><p>Dies ist ein eigenständiges Raspberry-Pi-Programm, keine HA-App zum Installieren im App-Store und keine offizielle Software von Home Assistant oder Elgato. Es ist <strong>kein USB-over-IP-Tunnel</strong>: Drucker oder Kameras werden damit nicht als entfernte USB-Geräte an HA durchgereicht.</p><p>Die Bilder stammen aus dem echten Nutzeraufbau mit 0.1.5. Die Oberfläche ist derzeit deutsch. Breite Bilder lassen sich durch Anklicken in Originalgröße öffnen.</p><p><a href="/images/usb-extender/key-list.png"><img src="'+n+'" alt="Breite Tastenliste mit MQTT-Kanälen"></a></p><h2 id="hardware" tabindex="-1">Welche Geräte werden erkannt? <a class="header-anchor" href="#hardware" aria-label="Permalink to &quot;Welche Geräte werden erkannt? {#hardware}&quot;">​</a></h2><p><strong>Erkannt</strong> bedeutet zunächst: Linux kann das USB-Gerät auflisten. <strong>Bedienbar</strong> bedeutet zusätzlich: Ein Treiber kann seine Eingaben lesen und das Gerät ist in der Oberfläche ausdrücklich freigegeben. Das ist nicht dasselbe.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Gerät</th><th>Was bereits vorgesehen ist</th><th>Prüfstand</th></tr></thead><tbody><tr><td>USB-Tastaturen, auch Windows-Medientastaturen</td><td>Tastencodes, Drücken/Loslassen, Umschalter, Tastenzustand, Klick/Doppelklick/Halten</td><td>Trust-/HCT-Tastaturen im Praxisaufbau genutzt</td></tr><tr><td>Lautstärke- und Medientasten</td><td><code>KEY_VOLUMEUP</code>, <code>KEY_VOLUMEDOWN</code>, <code>KEY_MUTE</code>; weitere vom Gerät gelieferte Play-/Titeltasten</td><td>Lautstärke/Stumm beobachtet; andere Tasten je Modell testen</td></tr><tr><td>HID-Makropads und USB-Fußtaster</td><td>Gleiche Verarbeitung, wenn Linux normale Tastencodes meldet</td><td>Modellabhängig; Rückmeldungen willkommen</td></tr><tr><td>Physische Elgato Stream Decks</td><td>Eigener HID-Treiber, Display- und Bedienfunktionen unten</td><td>Implementiert, noch kein physischer Stream-Deck-Test dieses Projekts</td></tr><tr><td>Andere Geräte mit LCD-Tasten</td><td>Tastencodes eventuell über HID; Displayfunktionen brauchen den passenden Herstellertreiber</td><td>Keine allgemeine Kompatibilitätszusage</td></tr><tr><td>Drucker, Kameras, USB-Speicher, Audiointerfaces, serielle Geräte und weitere Controller</td><td>Bestandsanzeige; besondere Nutzfunktionen brauchen eigene Adapter</td><td>Keine allgemeine Druck-, Kamera-, Audio-, MIDI- oder serielle Weiterleitung</td></tr><tr><td>Stream Deck Mobile / Tablet-App</td><td>Kein direktes USB-Gerät am Pi</td><td>Derzeit nicht angebunden</td></tr></tbody></table></div><p>Ein angezeigtes Gerät ist nicht automatisch aktiviert. Unter <strong>USB-Geräte</strong> kannst du einen Namen vergeben, <strong>Gerät für Eingaben freigeben</strong> wählen und die Zielbroker ankreuzen. Geräte ohne Seriennummer werden anhand ihres USB-Ports zugeordnet; beim Umstecken kann eine neue Zuordnung nötig sein.</p><p><a href="/images/usb-extender/devices.png"><img src="'+t+`" alt="USB-Bestand und ausdrückliche Eingabefreigabe"></a></p><h2 id="installation" tabindex="-1">Installation auf dem Pi <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation auf dem Pi {#installation}&quot;">​</a></h2><p>Empfohlen sind Raspberry Pi 4 und Raspberry Pi OS Lite <strong>64 Bit, Bookworm oder neuer</strong>, Python 3.11+, systemd, sudo sowie Internet für apt/PyPI. Mehrere Geräte mit Displays benötigen gegebenenfalls einen aktiven USB-Hub mit eigener Versorgung. 32-Bit-Pi-OS ist noch nicht praktisch bestätigt.</p><p>ZIP auf den Pi kopieren, im Terminal in den Downloadordner wechseln und ausführen:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unzip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unzip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> USB-Extender-Home-Assistant-0.1.5-Raspi4.zip</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> USB-Extender-Home-Assistant-0.1.5</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Der Installer zeigt neun Schritte, prüft Abhängigkeiten und installiert Fehlendes. Bei Updates sichert er vorhandene Daten unter <code>/var/backups/</code>; Einstellungen und Icons bleiben erhalten. Das ZIP ist kein vollständig offline nutzbares Systemabbild. Für spätere Updates das neue ZIP separat entpacken und dessen Installer ausführen.</p><p>Beim ersten Einrichten ein Webpasswort setzen; es gibt kein installiertes Standardpasswort. Falls nötig: <code>sudo usb-extender password</code>. Dann:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Im Browser <code>http://&lt;IP-des-Pi&gt;:8098</code> öffnen und anmelden. Die Beispieladressen auf den Bildern durch die eigenen Brokeradressen ersetzen. HTTP nur im vertrauten lokalen Netz verwenden, ansonsten VPN/HTTPS davor setzen; nicht ins Internet freigeben.</p><h2 id="setup" tabindex="-1">Broker einrichten und Tasten anlernen <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Broker einrichten und Tasten anlernen {#setup}&quot;">​</a></h2><ol><li>Unter <strong>MQTT-Broker</strong> Host, Port und gegebenenfalls Zugangsdaten eintragen. Gewünschte Verbindungen aktivieren und speichern. Pro Broker arbeitet eine eigene Verbindung; eine Taste kann alle drei Ziele erreichen.</li><li>Auf HA-Brokern Discovery aktivieren. Für ioBroker <strong>Aus – nur MQTT-Daten senden</strong> wählen, damit der HA-Discovery-Adapter nicht über Geräteauslöser klagt.</li><li>Unter <strong>USB-Geräte</strong> Gerät benennen, freigeben, Ziele wählen und speichern.</li><li>Unter <strong>Tasten &amp; Anzeigen</strong> das Gerät wählen und <strong>Anlernen starten</strong> drücken. Jede gewünschte Taste einmal drücken und loslassen. Wiederholte und bereits vorhandene Tasten werden nicht doppelt angelegt.</li><li><strong>Anlernen beenden → Tasten übernehmen → Speichern</strong>. Erst jetzt sind neue Zeilen aktiv. Während des Anlernens sendet das ausgewählte Gerät keine Aktionen.</li><li>Pro Zeile Kanäle abwählen oder Topics/Namen ändern. <strong>Bearbeiten</strong> öffnet Brokerwahl, Switch-Verhalten und Zeitwerte. Neue Zusatzkanäle vorhandener Zeilen bleiben zunächst aus; neu angelernte Zeilen haben alle Kanäle vorbereitet.</li></ol><p><a href="/images/usb-extender/brokers.png"><img src="`+s+'" alt="Drei Brokerplätze im Praxisaufbau"></a></p><p><a href="/images/usb-extender/learning.png"><img src="'+i+'" alt="Anlernmodus mit gewähltem USB-Gerät"></a></p><p>Wird das Browserfenster während des Anlernens geschlossen, endet die Pause spätestens nach 15 Sekunden ohne Rückmeldung. Anlernentwürfe liegen bis zum Übernehmen/Speichern nur im Browser. Bereits gespeicherte Belegungen bleiben erhalten.</p><h2 id="topics" tabindex="-1">Topics und Tastenfunktionen <a class="header-anchor" href="#topics" aria-label="Permalink to &quot;Topics und Tastenfunktionen {#topics}&quot;">​</a></h2><p>Aus Gerätename <strong>Trust1</strong> und Taste <strong>F1</strong> entsteht beispielsweise <code>trust1-key-f1/press</code>. Namen werden MQTT-tauglich geschrieben; Umlaute wie in „Büro“ werden zu <code>buero</code>. Doppelte Gerätenamen bekommen bei Bedarf <code>-2</code>, <code>-3</code> usw. Gespeicherte Topics bleiben bei späterer Umbenennung stabil und haben an allen ausgewählten Brokern denselben Namen. Sie lassen sich einzeln bearbeiten.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Endung hinter <code>trust1-key-f1</code></th><th>Nachricht und Funktion</th></tr></thead><tbody><tr><td><code>/press</code></td><td><code>press</code> sofort beim Drücken</td></tr><tr><td><code>/release</code></td><td><code>release</code> beim Loslassen</td></tr><tr><td><code>/press-plus</code>, <code>/release-plus</code></td><td>Gleiche Aktion, nach 50 ms leere Nachricht auf genau diesem Kanal</td></tr><tr><td><code>/switch</code></td><td>Erster Druck <code>ON</code>, nächster Druck <code>OFF</code>; Loslassen ändert nichts</td></tr><tr><td><code>/state</code></td><td>Gedrückt <code>ON</code>, losgelassen <code>OFF</code></td></tr><tr><td><code>/button</code></td><td>Je nach Bedienung <code>click</code>, <code>double_click</code> oder <code>hold</code></td></tr><tr><td><code>/button-plus</code></td><td>Gleiche Button-Aktion, danach nach 50 ms leer</td></tr><tr><td><code>/click</code>, <code>/double-click</code>, <code>/hold</code></td><td>Die jeweilige einzelne Geste</td></tr></tbody></table></div><p><code>plus</code> wird ausgeschrieben, weil <code>+</code> in MQTT ein Platzhalter ist. Alle elf Kanäle sind einzeln aktivierbar. Nur die Plus-Kanäle werden leer zurückgesetzt; leer bedeutet <strong>nicht</strong> Loslassen. Der Switch-Wert bleibt in <code>switches.json</code> über App-Neustarts erhalten und wird beim Wiederverbinden erneut synchronisiert.</p><p><strong>Klick/Doppelklick/Halten:</strong> Ein Klick wartet das Doppelklick-Fenster ab (Vorgabe 300 ms nach Loslassen). Ein zweiter Klick darin ergibt nur <code>double_click</code>. Halten ab 700 ms ergibt einmal <code>hold</code>, ohne Klick beim Loslassen. Wird der zweite Druck gehalten, ersetzt Hold die wartende Klickfolge. Zeiten sind pro Taste einstellbar. Normale Tastaturwiederholungen zählen nicht als weitere Klicks oder Switch-Betätigungen.</p><p><strong>Lauter/Leiser:</strong> Aktive Press-/Press+-Kanäle können beim Halten wiederholt werden, standardmäßig nach 500 ms alle 150 ms. Loslassen beendet die Wiederholung; zusätzlich gilt ein Sicherheitsstopp nach 30 Sekunden. Die Lautstärkeschrittweite bestimmt deine HA-Automation bzw. ioBroker-Logik. Normale Press-/Release-Kanäle bleiben unabhängig von der verzögerten Button-Erkennung sofort verfügbar.</p><p>Die App sendet Tastenmeldungen mit QoS 0 und ohne Retain. Offline-Eingaben werden nicht nachgesendet. Mehrere aktive Kanäle können mehrere zugeordnete Automationen auslösen; für eine einzelne Funktion den passenden Kanal auswählen.</p><h2 id="integration" tabindex="-1">Anzeige in Home Assistant und ioBroker <a class="header-anchor" href="#integration" aria-label="Permalink to &quot;Anzeige in Home Assistant und ioBroker {#integration}&quot;">​</a></h2><p>HA-Discovery fasst alle Tasten unter dem gewählten Gerätenamen mit einer gemeinsamen stabilen Gerätekennung zusammen. Aktionen werden als Geräteauslöser mit Payloadfilter angeboten. Switch und Tastenzustand sind <strong>Binärsensoren</strong>, die Zustände anzeigen; zum Schalten anderer Geräte braucht es eine Automation oder Zuordnung.</p><img src="'+a+'" alt="HA zeigt Switch Ein und Tastenzustand Aus nach dem Loslassen" width="280"><p>Im Nutzerbild ist Switch nach der Betätigung <strong>Ein</strong>, der Tastenzustand nach dem Loslassen <strong>Aus</strong>. Zunächst unbekannte Werte können vor der ersten empfangenen Zustandsmeldung auftreten; das ist kein Nachweis einer defekten Tastenerkennung.</p><details><summary>Bild vor den ersten Zustandsmeldungen</summary><img src="'+r+'" alt="HA-Zustände vor den ersten empfangenen Tastenwerten" width="280"></details><p>In ioBroker entstehen unter dem MQTT-Adapter einzelne Datenpunkte, sobald die jeweiligen Topics erstmals empfangen werden. Das Praxisbild zeigt einfache Werte wie <code>press</code>, <code>release</code>, <code>click</code>, <code>hold</code>, <code>ON</code> und <code>OFF</code>. Plus-Kanäle stehen nach der leeren Rücksetzung hier auf <code>(null)</code>. Das ist erwartbar; der Datenpunkt bleibt bestehen. Ein Doppelklick-Datenpunkt erscheint erst, wenn tatsächlich eine passende Nachricht gesendet wurde. Alte Datenpunkte mit dem früheren JSON-Ereigniswert ändern sich nicht automatisch. Discovery-Konfigurationen bleiben absichtlich JSON.</p><p><a href="/images/usb-extender/iobroker-states.png"><img src="'+d+`" alt="Einzelne Datenpunkte mit einfachen Werten in ioBroker"></a></p><h2 id="stream-deck" tabindex="-1">Stream Deck und ähnliche Geräte <a class="header-anchor" href="#stream-deck" aria-label="Permalink to &quot;Stream Deck und ähnliche Geräte {#stream-deck}&quot;">​</a></h2><p>Der integrierte <code>python-elgato-streamdeck</code>-Treiber 0.10.0 kennt unter anderem Original/MK.2, Mini, XL, Neo, Pedal und Plus. Diese Modellliste beschreibt den Treiberumfang, <strong>keinen bereits durchgeführten Hardwaretest</strong> dieses Projekts.</p><ul><li>Displaytasten: eigene Icons und Text, Helligkeit pro Gerät, MQTT-Zustandsrückmeldung zum Wechseln eines Icons und gezielte Displayaufträge.</li><li>Tasten: Press/Release, Klick/Doppelklick/Hold, Switch und Tastenzustand wie oben.</li><li>Drehregler, wenn vorhanden: Drehrichtung und Druck als Eingaben.</li><li>Touchscreen, wenn vorhanden: Touch-Ereignisse; kein frei gestaltbarer Touchscreen-Editor.</li><li>Pedal und andere Modelle ohne Display: Eingaben, aber keine Display-Icons.</li><li>Eine feste Belegung; Profil-/Seitenwechsel und animierte Tastenicons sind noch offen.</li></ul><p>Unter <strong>Iconbibliothek</strong> eigene Bilddateien oder einen Ordner auf dem Pi einlesen. Auch lokal gespeicherte ZIP- und <code>.streamDeckIconPack</code>-Pakete sind möglich. Es wird nichts automatisch aus dem Elgato Marketplace heruntergeladen. Rechte des jeweiligen Iconpacks beachten; bei Animationen nutzt die App das erste Bild.</p><p>Bei Fremdgeräten mit ähnlicher Optik kann der Tastaturteil bereits über HID funktionieren. LCDs, Touch und herstellerspezifische Befehle benötigen eventuell einen eigenen Adapter. Bitte ein konkretes Modell testen und berichten, statt von der äußeren Ähnlichkeit auf vollständige Kompatibilität zu schließen.</p><h2 id="operation" tabindex="-1">Weboberfläche abschalten und sichern <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Weboberfläche abschalten und sichern {#operation}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ugso-usbhub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><code>web stop</code> beendet den HTTP-Listener; das Schließen des Browsers allein tut das nicht. Der USB-/MQTT-Dienst läuft weiter. Einstellungen, Icons und Switch-Werte liegen unter <code>/var/lib/ugso-usbhub/</code>. Die letzten zehn Konfigurationsstände werden automatisch gesichert; eine vollständige CLI-Sicherung enthält auch Icons und Switch-Werte. Backups nicht öffentlich hochladen.</p><p><a href="/images/usb-extender/system.png"><img src="`+l+'" alt="Systembefehle und Diagnoseseite"></a></p><h2 id="tests" tabindex="-1">Was ist praktisch nachgewiesen? <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Was ist praktisch nachgewiesen? {#tests}&quot;">​</a></h2><p>Die Nutzerbilder zeigen 0.1.5, drei online gemeldete Brokerplätze, angelernte Funktionstasten, HA-Zustände und einzelne ioBroker-Datenpunkte. Im Verlauf ist die Übergabe an HA, IOB und Testserver sichtbar. Die Übergabeanzeige allein beweist keinen Empfang bei jedem Broker; HA-/ioBroker-Bilder liefern den zusätzlichen sichtbaren Nachweis. Nicht jede Funktion ist dadurch an jeder Hardware geprüft.</p><p><a href="/images/usb-extender/events.png"><img src="'+o+'" alt="F12-Ereignisse mit ausgewählten Topics und drei MQTT-Zielen"></a></p><p>Zusätzlich bestehen 61 lokale Python-Prüfungen und zwei JavaScript-/DOM-Prüfläufe, unter anderem für Doppelklick, Switch-Neustartpersistenz, Routing und Fehlerfälle. Ein physischer Stream-Deck-Test bleibt offen.</p><h2 id="feedback" tabindex="-1">Eigene Hardware testen und Rückmeldung geben <a class="header-anchor" href="#feedback" aria-label="Permalink to &quot;Eigene Hardware testen und Rückmeldung geben {#feedback}&quot;">​</a></h2><p>Besitzt du ein Stream Deck, ein ähnliches LCD-Tastengerät, Makropad oder USB-Pedal? Teste es gern und <a href="https://github.com/rockbaer2007/usb-extender-home-assistant/issues/new?template=hardware-test.yml" target="_blank" rel="noreferrer">melde deine Ergebnisse auf GitHub</a>. Fehlerberichte und Mitarbeit sind willkommen.</p><p>Bitte Modell/Revision, Pi-Modell, Betriebssystem und App-Version nennen. Unterscheide Bestandsanzeige und echte Tastencodes. Berichte getrennt über Drücken/Loslassen, Klick/Doppelklick/Halten, Icons/Text, Helligkeit, Drehregler, Touch und Wiederanstecken; nicht geprüfte Funktionen ausdrücklich so markieren. Nutze zuerst ein unkritisches MQTT-Topic ohne echte Geräteaktionen. Screenshots von Bestand und Ereignissen helfen. Keine Passwörter, Tokens, <code>config.json</code> oder Sicherungsarchive veröffentlichen.</p>',55)])])}const y=h(k,[["render",g]]);export{E as __pageData,y as default};
